const PressTokens = function Render() {
  const [down, setDown] = useState<ButtonVariant | null>(null);
  return (
    <div style={{ display: 'flex', gap: 32, flexWrap: 'wrap', justifyContent: 'center' }}>
      {VARIANTS.map((variant) => {
        const on = down === variant;
        const t = STATE_TOKENS[variant][on ? 'Pressed' : 'Default'];
        const set = (v: ButtonVariant | null) => () => setDown(v);
        return (
          <figure key={variant} style={{ margin: 0, display: 'grid', justifyItems: 'center', gap: 10, minWidth: 180 }}>
            <Button
              variant={variant}
              onPointerDown={set(variant)}
              onPointerUp={set(null)}
              onPointerLeave={set(null)}
              onPointerCancel={set(null)}
            >
              {NAMES[variant]}
            </Button>
            <figcaption style={{ display: 'grid', justifyItems: 'center', gap: 2 }}>
              <TokenTag cssVar={t.bg} />
              <Caption>{on ? 'scale 0.97 · 100 мс' : 'scale 1 · 240 мс назад'}</Caption>
            </figcaption>
          </figure>
        );
      })}
    </div>
  );
};

const Loaders = function Render() {
  const [on, setOn] = useState(true);
  const [busy, setBusy] = useState<ButtonLoader | null>(null);
  const run = (kind: ButtonLoader) => () => {
    setBusy(kind);
    window.setTimeout(() => setBusy((b) => (b === kind ? null : b)), 2500);
  };
  return (
    <div style={{ display: 'grid', gap: 20 }}>
      <div>
        <Button variant="secondary" size={40} radius="full" onClick={() => setOn((v) => !v)}>
          {on ? 'Выключить загрузку' : 'Включить загрузку'}
        </Button>
      </div>
      <div style={{ display: 'grid', gridTemplateColumns: 'minmax(160px, 220px) repeat(3, auto) auto', gap: '16px 20px', alignItems: 'center' }}>
        <span />
        {VARIANTS.map((v) => (
          <Caption key={v} strong>
            {NAMES[v]}
          </Caption>
        ))}
        <Caption strong>Нажми</Caption>
        {LOADERS.map(({ kind, name, note }) => (
          <Fragment key={kind}>
            <span style={{ display: 'grid', gap: 2 }}>
              <Caption strong>{name}</Caption>
              <Caption>{note}</Caption>
            </span>
            {VARIANTS.map((variant) => (
              <span key={variant}>
                <Button variant={variant} loading={on} loader={kind}>
                  Оплатить
                </Button>
              </span>
            ))}
            <span>
              <Button loader={kind} loading={busy === kind} onClick={run(kind)}>
                Оплатить 12 400 ⃀
              </Button>
            </span>
          </Fragment>
        ))}
      </div>
    </div>
  );
};

